// File: components/landing/interactive-preview.tsx
"use client";

import { motion } from "motion/react";
import { useState } from "react";
import { cn } from "@/lib/utils";
import { Code, Palette, Zap } from "lucide-react";

interface Feature {
  icon: React.ReactNode;
  title: string;
  description: string;
  preview: React.ReactNode;
}

const FEATURES: Feature[] = [
  {
    icon: <Code className="w-5 h-5" />,
    title: "Copy & Paste Ready",
    description:
      "Every component is ready to be copied directly into your project.",
    preview: (
      <div className="w-full h-full bg-[#1e1e1e] rounded-lg p-4 font-mono text-xs overflow-hidden">
        <div className="flex gap-1.5 mb-3">
          <div className="w-2.5 h-2.5 rounded-full bg-[#ff5f56]" />
          <div className="w-2.5 h-2.5 rounded-full bg-[#ffbd2e]" />
          <div className="w-2.5 h-2.5 rounded-full bg-[#27c93f]" />
        </div>
        <pre className="text-muted-foreground">
          <code>
            <span className="text-pink-400">export function</span>{" "}
            <span className="text-blue-400">Button</span>() {"{"}
            <br />
            &nbsp;&nbsp;<span className="text-pink-400">return</span> (<br />
            &nbsp;&nbsp;&nbsp;&nbsp;&lt;
            <span className="text-blue-400">button</span>{" "}
            <span className="text-green-400">className</span>...&ldquo;&gt;
            <br />
            &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Click me
            <br />
            &nbsp;&nbsp;&nbsp;&nbsp;&lt;/
            <span className="text-blue-400">button</span>&gt;
            <br />
            &nbsp;&nbsp;);
            <br />
            {"}"}
          </code>
        </pre>
      </div>
    ),
  },
  {
    icon: <Palette className="w-5 h-5" />,
    title: "Fully Customizable",
    description: "Tailwind-based styling that's easy to modify and extend.",
    preview: (
      <div className="grid grid-cols-3 gap-2">
        {[
          "bg-blue-500",
          "bg-emerald-500",
          "bg-purple-500",
          "bg-amber-500",
          "bg-pink-500",
          "bg-cyan-500",
        ].map((color, i) => (
          <div
            key={i}
            className={cn(
              "aspect-square rounded-lg transition-transform hover:scale-105",
              color,
            )}
          />
        ))}
      </div>
    ),
  },
  {
    icon: <Zap className="w-5 h-5" />,
    title: "Interactive Elements",
    description: "Smooth animations and transitions built-in.",
    preview: (
      <div className="flex items-center justify-center">
        <motion.div
          animate={{
            scale: [1, 1.2, 1],
            rotate: [0, 180, 360],
          }}
          transition={{
            duration: 2,
            repeat: Infinity,
            ease: "easeInOut",
          }}
          className="w-16 h-16 bg-linear-to-r from-indigo-500 via-purple-500 to-pink-500 rounded-2xl"
        />
      </div>
    ),
  },
];

export function InteractivePreview() {
  const [activeFeature, setActiveFeature] = useState(0);

  return (
    <div className="w-full max-w-6xl mx-auto px-4 py-16">
      <div className="grid grid-cols-1 lg:grid-cols-[1fr_1.5fr] gap-8">
        <div className="space-y-8">
          {FEATURES.map((feature, index) => (
            <motion.div
              key={index}
              className={cn(
                "p-6 rounded-2xl cursor-pointer",
                activeFeature === index
                  ? "bg-muted"
                  : "hover:bg-muted/50",
              )}
              onClick={() => setActiveFeature(index)}
              whileHover={{ x: 5 }}
              transition={{ duration: 0.2 }}
            >
              <div className="flex items-start gap-4">
                <div className="p-2 rounded-lg bg-muted">
                  {feature.icon}
                </div>
                <div>
                  <h3 className="font-semibold text-lg mb-1">
                    {feature.title}
                  </h3>
                  <p className="text-sm text-muted-foreground">
                    {feature.description}
                  </p>
                </div>
              </div>
            </motion.div>
          ))}
        </div>

        <div className="lg:h-100 p-8 rounded-3xl bg-linear-to-b from-background to-muted/50 border border-border">
          <motion.div
            key={activeFeature}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3 }}
            className="w-full h-full"
          >
            {FEATURES[activeFeature].preview}
          </motion.div>
        </div>
      </div>
    </div>
  );
}
